package com.example.llama

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView

data class Message(
    val id: String,
    val content: String,
    val isUser: Boolean
)

class MessageAdapter(
    private val messages: List<Message>
) : RecyclerView.Adapter<RecyclerView.ViewHolder>() {

    companion object {
        private const val VIEW_TYPE_USER = 1
        private const val VIEW_TYPE_ASSISTANT = 2
    }

    override fun getItemViewType(position: Int): Int {
        return if (messages[position].isUser) VIEW_TYPE_USER else VIEW_TYPE_ASSISTANT
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        val layoutInflater = LayoutInflater.from(parent.context)
        return if (viewType == VIEW_TYPE_USER) {
            val view = layoutInflater.inflate(R.layout.item_message_user, parent, false)
            UserMessageViewHolder(view)
        } else {
            val view = layoutInflater.inflate(R.layout.item_message_assistant, parent, false)
            AssistantMessageViewHolder(view)
        }
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        val message = messages[position]
        if (holder is UserMessageViewHolder || holder is AssistantMessageViewHolder) {
            val textView = holder.itemView.findViewById<TextView>(R.id.msg_content)
            textView.text = message.content
        }
    }

    override fun getItemCount(): Int = messages.size

    class UserMessageViewHolder(view: View) : RecyclerView.ViewHolder(view)
    class AssistantMessageViewHolder(view: View) : RecyclerView.ViewHolder(view)
}

from __future__ import annotations

from typing import Any, Callable, TYPE_CHECKING

if TYPE_CHECKING:
    from torch import Tensor

from .base import ModelBase, gguf
from .qwen import Qwen3Model
from .ultravox import WhisperEncoderModel


# plain ChatML as built by transcribe.py upstream, the Qwen3 template renders past assistant turns differently from the last one
HIGGS_AUDIO_CHAT_TEMPLATE = (
    "{%- for message in messages -%}"
    "{{- '<|im_start|>' + message['role'] + '\\n' + message['content'] + '<|im_end|>\\n' -}}"
    "{%- endfor -%}"
    "{%- if add_generation_prompt -%}"
    "{{- '<|im_start|>assistant\\n' -}}"
    "{%- if enable_thinking is defined and enable_thinking is false -%}"
    "{{- '<think>\\n\\n</think>\\n\\n' -}}"
    "{%- endif -%}"
    "{%- endif -%}"
)


@ModelBase.register("HiggsAudio3Model")
@ModelBase.example("bosonai/higgs-audio-v3-stt")
class HiggsAudioModel(Qwen3Model):
    model_arch = gguf.MODEL_ARCH.QWEN3

    def set_vocab(self):
        super().set_vocab()
        self.gguf_writer.add_chat_template(HIGGS_AUDIO_CHAT_TEMPLATE)

    @classmethod
    def filter_tensors(cls, item: tuple[str, Callable[[], Tensor]]) -> tuple[str, Callable[[], Tensor]] | None:
        name, gen = item

        # the audio_* tensors are dropped by TextModel, rename the text head before that
        if name == "audio_decoder_proj.text_lm_head.weight":
            name = "lm_head.weight"
        else:
            name = "model." + name

        return super().filter_tensors((name, gen))


@ModelBase.register("HiggsAudio3Model")
class HiggsAudioWhisperEncoderModel(WhisperEncoderModel):
    has_vision_encoder = False
    has_audio_encoder = True

    def get_audio_config(self) -> dict[str, Any] | None:
        return self.global_config["audio_encoder_config"]

    def tensor_force_quant(self, name, new_name, bid, n_dims):
        # depthwise conv kernel, same as the whisper convs
        if name == "audio_encoder_proj.temporal.weight":
            return gguf.GGMLQuantizationType.F16
        return super().tensor_force_quant(name, new_name, bid, n_dims)

    def set_gguf_parameters(self):
        assert self.global_config["projector_type"] == "mlp" and self.global_config["projector_temporal_downsample"] == 2
        assert self.global_config["audio_adapter_type"] == "stack" and not self.global_config.get("duplicate_audio_triplet", False)
        super().set_gguf_parameters()
        self.gguf_writer.add_clip_projector_type(gguf.VisionProjectorType.HIGGS_AUDIO)

    @classmethod
    def filter_tensors(cls, item: tuple[str, Callable[[], Tensor]]) -> tuple[str, Callable[[], Tensor]] | None:
        name, _ = item
        if not name.startswith(("audio_tower.", "audio_encoder_proj.")):
            return None
        return super().filter_tensors(item)

/** Image handling constants */

export const IMAGE = {
	/** JPEG quality used when transcoding HEIC images. */
	HEIC_JPEG_QUALITY: 0.85,
	/** Unit conversion: pixels per megapixel. */
	MEGAPIXELS_TO_PIXELS: 1_000_000
} as const;

/**
 * JPEG and EXIF binary format constants for orientation parsing.
 */
export const EXIF = {
	/** APP1 segment marker byte, carries the EXIF payload */
	APP1_MARKER: 0xe1,
	/** "Exif" signature opening the APP1 payload, big endian uint32 */
	EXIF_SIGNATURE: 0x45786966,
	/** Size in bytes of one IFD directory entry */
	IFD_ENTRY_SIZE: 12,
	/** JPEG start of image marker */
	JPEG_SOI_MARKER: 0xffd8,
	/** EXIF tag id holding the orientation value */
	ORIENTATION_TAG: 0x0112,
	/** Bytes of file prefix to scan, the APP1 EXIF segment sits near the start */
	SCAN_BYTE_LIMIT: 128 * 1024,
	/** Start of scan marker byte, compressed data begins and no EXIF follows */
	SOS_MARKER: 0xda,
	/** TIFF byte order mark for little endian ("II") */
	TIFF_LITTLE_ENDIAN: 0x4949,
	/** TIFF magic number following the byte order mark */
	TIFF_MAGIC: 42
} as const;
